var ErrNotFound = errors.New("user not found")

func findUser(ctx context.Context, id int64) (User, error) {
    user, err := repo.Find(ctx, id)
    if errors.Is(err, sql.ErrNoRows) { return User{}, ErrNotFound }
    if err != nil { return User{}, fmt.Errorf("find user %d: %w", id, err) }
    return user, nil
}
